#!/usr/bin/env bash
set -uo pipefail
ROOT="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.." && pwd)"; TMP="$(mktemp -d "${TMPDIR:-/tmp}/gentle-ai-rubric-activation.XXXXXX")"; trap 'rm -rf -- "$TMP"' EXIT; PASS=0; FAIL=0
ok() { printf 'PASS: %s\n' "$1"; PASS=$((PASS + 1)); }; no() { printf 'FAIL: %s\n' "$1" >&2; FAIL=$((FAIL + 1)); }; reject() { "$@" >/dev/null 2>&1; }
extract_block() { awk -v s="$1" -v n="$2" '$0=="<!-- shape:"s" -->"{a=1;next}$0=="<!-- /shape:"s" -->"{exit}a&&$0=="<!-- rubric-"n":start -->"{b=1;next}a&&$0=="<!-- rubric-"n":end -->"{exit}b{print}' "$ROOT/deltas/sdd-init-rubric.md" > "$3"; chmod +x "$3"; }
field() { awk -F= -v k="$2" '$1==k{n++;v=substr($0,length(k)+2)}END{if(n==1)print v;else exit 1}' "$1"; }
model() { field "$1" canonical_model_bytes | sed 's/^hex://' | xxd -r -p; }
receipt() { for k in schema state gate_version gate_digest integrated_bundle_digest semantic_digest canonical_model_bytes canonical_model_digest commits; do field "$1" "$k" >/dev/null || return 1; done; grep -Fxq 'schema=IntegratedValidationV1' "$1" && grep -Fxq 'state=verified' "$1" && grep -Fxq 'gate_version=v1' "$1" && grep -Fxq 'commits=none' "$1"; }
definitions() { awk -v n="$2" '$0 ~ ("^" n "\\(\\)") { c++ } END { print c+0 }' "$1"; }
outside() { local in=$1 part=$2 start end; start=$(awk '/^testing:[[:space:]]*$/{n++;x=NR}END{if(n==1)print x;else exit 1}' "$in") || return 1; end=$(awk -v n="$start" 'NR>n&&/^[A-Za-z_][A-Za-z0-9_-]*:/{print NR;exit}' "$in") || return 1; case "$part" in prefix) awk -v n="$start" 'NR<n{print}';; suffix) awk -v n="$end" 'NR>=n{print}';; esac < "$in"; }
# shellcheck disable=SC1091
source "$ROOT/tests/lib/rubric-compiler-cnsic-fixture.sh"; rccf_load_unit1a "$ROOT" "$TMP"
# shellcheck disable=SC1091
source "$ROOT/tests/lib/rubric-engram-store.sh"
extract_block details adapter-gate "$TMP/gate"; extract_block pi adapter-gate "$TMP/pi"; extract_block details adapter-records "$TMP/records"; extract_block details validator "$TMP/validator"; extract_block details activation "$TMP/activation"; extract_block pi activation "$TMP/pi-activation"
cmp -s "$TMP/gate" "$TMP/pi" && [ -s "$TMP/gate" ] && ok 'Details and Pi integrated gate bytes match' || no 'missing or divergent integrated gate'
cmp -s "$TMP/activation" "$TMP/pi-activation" && [ -s "$TMP/activation" ] && ok 'Details and Pi activation transaction bytes match' || no 'missing or divergent activation transaction'
for n in model ms mval mf mr ml mvs mid mrefs mobs mfact matt mbind mrow; do [ "$(definitions "$TMP/gate" "$n")" = 1 ] && [ "$(definitions "$TMP/pi" "$n")" = 1 ] || { no "duplicate or missing canonical serializer $n"; break; }; done; [ "$FAIL" -eq 0 ] && ok 'each gate defines one canonical serializer' || :
b="$TMP/candidate"; rccf_cnsic_candidate "$b"; "$TMP/validator" "$b" >/dev/null && ok 'shared CNSIC fixture is exact Unit1A-valid' || no 'shared CNSIC fixture is not Unit1A-valid'
"$TMP/records" records "$b" "$TMP/records-set" && "$TMP/gate" integrate "$b" "$TMP/records-set" "$TMP/integrated" && rccf_confirm "$TMP/integrated" && "$TMP/validator" "$TMP/integrated" >/dev/null && ok 'real candidate records integrate and canonical confirmation rebuilds Unit1A identities' || no 'real pipeline or canonical confirmation failed'
"$TMP/gate" verify-integrated "$TMP/integrated" "$TMP/pre-activation" || no 'pre-activation integrated receipt failed'
