cp "$TMP/actual.yaml" "$TMP/actual-once"; "$TMP/activation" activate-openspec cnsic "$TMP/integrated" "$TMP/actual.yaml" "$TMP/actual-resolution-two" "$TMP/gate" && cmp -s "$TMP/actual-once" "$TMP/actual.yaml" && cmp -s "$TMP/actual.prefix" <(outside "$TMP/actual.yaml" prefix) && cmp -s "$TMP/actual.suffix" <(outside "$TMP/actual.yaml" suffix) && ok 'actual config repeat preserves exact prefix and suffix' || no 'actual config repeat changed exterior bytes'
cat > "$TMP/config.yaml" <<'EOF'
context: "preserve"
testing:
  legacy: "replace"
strict_tdd: false
rules:
  apply: "preserve"
EOF
cp "$TMP/config.yaml" "$TMP/config-before"; "$TMP/activation" activate-openspec cnsic "$TMP/integrated" "$TMP/config.yaml" "$TMP/resolution" "$TMP/gate" && grep -Fq '# gentle-ai:managed-testing:start' "$TMP/config.yaml" && grep -Fq 'command:' "$TMP/config.yaml" && grep -Fq 'rows:' "$TMP/config.yaml" && grep -Fq 'context: "preserve"' "$TMP/config.yaml" && grep -Fq 'rules:' "$TMP/config.yaml" && [ "$(field "$TMP/resolution" canonical_model_digest)" = "$(field "$TMP/pre-activation" canonical_model_digest)" ] && ok 'pinned gate serializes complete YAML and preserves unrelated bytes' || no 'OpenSpec serializer or transaction failed'
cp "$TMP/config.yaml" "$TMP/config-once"; "$TMP/activation" activate-openspec cnsic "$TMP/integrated" "$TMP/config.yaml" "$TMP/resolution-two" "$TMP/gate" && cmp -s "$TMP/config-once" "$TMP/config.yaml" && ok 'activation is byte-idempotent' || no 'activation was not idempotent'
cp "$TMP/config-before" "$TMP/pi-config.yaml"; "$TMP/pi-activation" activate-openspec cnsic "$TMP/integrated" "$TMP/pi-config.yaml" "$TMP/pi-resolution" "$TMP/pi" && cmp -s "$TMP/config.yaml" "$TMP/pi-config.yaml" && ok 'Pi activation executes the exact Details transaction' || no 'Pi activation differs from Details transaction'
for kind in zero multiple tabs directive anchor alias tag merge block partial; do cp "$TMP/config-before" "$TMP/$kind.yaml"; case "$kind" in zero) printf '%s\n' 'context: "x"' 'strict_tdd: false' 'rules: {}' > "$TMP/$kind.yaml";; multiple) printf '%s\n' 'testing:' '  x: y' 'testing:' '  z: q' 'strict_tdd: false' 'rules: {}' > "$TMP/$kind.yaml";; tabs) printf '\ttesting:\n' >> "$TMP/$kind.yaml";; directive) printf '%s\n' '---' >> "$TMP/$kind.yaml";; anchor) printf '%s\n' 'x: &shared value' >> "$TMP/$kind.yaml";; alias) printf '%s\n' 'x: *shared' >> "$TMP/$kind.yaml";; tag) printf '%s\n' 'x: !unsafe value' >> "$TMP/$kind.yaml";; merge) printf '%s\n' '<<: *shared' >> "$TMP/$kind.yaml";; block) printf '%s\n' 'context: "x"' 'testing:' '  legacy: |' '    block' 'strict_tdd: false' 'rules: {}' > "$TMP/$kind.yaml";; partial) printf '%s\n' '  # gentle-ai:managed-testing:start' >> "$TMP/$kind.yaml";; esac; cp "$TMP/$kind.yaml" "$TMP/$kind.before"; ! reject "$TMP/activation" activate-openspec cnsic "$TMP/integrated" "$TMP/$kind.yaml" "$TMP/$kind.result" "$TMP/gate" && cmp -s "$TMP/$kind.before" "$TMP/$kind.yaml" && [ ! -e "$TMP/$kind.result" ] && ok "$kind target rejects unchanged" || no "$kind target changed or accepted"; done
cp "$TMP/gate" "$TMP/substituted-gate"; printf x >> "$TMP/substituted-gate"; ! reject "$TMP/activation" activate-openspec cnsic "$TMP/integrated" "$TMP/config-before" "$TMP/substituted-result" "$TMP/substituted-gate" && [ ! -e "$TMP/substituted-result" ] && ok 'substituted or extra caller policy input rejects' || no 'unpinned gate accepted'; ! reject "$TMP/activation" activate-openspec cnsic "$TMP/integrated" "$TMP/config-before" "$TMP/extra-result" "$TMP/gate" extra && ok 'caller policy argument is impossible' || no 'caller policy argument was accepted'
before=$(cksum "$TMP/config-before"); out=$("$TMP/activation" evaluate-none cnsic "$TMP/integrated" "$TMP/gate") && [ "$(cksum "$TMP/config-before")" = "$before" ] && [ ! -e "$TMP/none-result" ] && printf '%s' "$out" | grep -Fq 'canonical_model_digest=' && ok 'none prints model envelope with zero target or receipt writes' || no 'none mode wrote or omitted model'
rces_init "$TMP/engram-store"
