grep -Fxq 'state=active' "$TMP/engram-resolution" && grep -Fxq 'engram_preimage_presence=absent' "$TMP/engram-resolution" && grep -Fxq 'state=active' <(rces_field "$TMP/engram-store/current" content_hex | xxd -r -p) && ok 'active resolution follows both verified read-backs with readable model metadata' || no 'resolution or canonical Markdown metadata was incomplete'
printf 'prior canonical bytes\n' > "$TMP/prior"; rces_init "$TMP/update-store"; rces_seed "$TMP/update-store" sdd-init/cnsic "$TMP/prior"; prior_hex=$(rces_hex "$TMP/prior"); prior_digest=$(rces_digest "$TMP/prior"); "$TMP/activation" activate-engram cnsic "$TMP/integrated" "$ROOT/tests/lib/rubric-engram-store.sh" "$TMP/update-store" "$TMP/gate" > "$TMP/update-resolution" && grep -Fxq 'engram_preimage_presence=found' "$TMP/update-resolution" && grep -Fxq 'engram_preimage_revision=1' "$TMP/update-resolution" && grep -Fxq "engram_preimage_digest=$prior_digest" "$TMP/update-resolution" && grep -Fxq "engram_preimage_hex=$prior_hex" "$TMP/update-resolution" && ok 'existing active update retains exact preimage metadata' || no 'existing preimage metadata was lost'
for fault in malformed duplicate ambiguous version-only error stale lie-put post-missing post-mismatch; do rces_init "$TMP/$fault-store"; rces_mode "$TMP/$fault-store" "$fault"; ! reject "$TMP/activation" activate-engram cnsic "$TMP/integrated" "$ROOT/tests/lib/rubric-engram-store.sh" "$TMP/$fault-store" "$TMP/gate" && { [ ! -f "$TMP/$fault-store/current" ] || ! grep -Fxq 'state=active' <(rces_field "$TMP/$fault-store/current" content_hex | xxd -r -p); } && ok "$fault adapter failure cannot report active" || no "$fault adapter failure was accepted"; done
rces_request "$TMP/bad-request" schema EngramAdapterV1 verb unknown request_id one project cnsic topic sdd-init/cnsic; ! reject "$ROOT/tests/lib/rubric-engram-store.sh" "$TMP/engram-store" "$TMP/bad-request" "$TMP/bad-response" && rces_request "$TMP/bad-request" schema EngramAdapterV1 verb lookup-canonical request_id one project cnsic && ! reject "$ROOT/tests/lib/rubric-engram-store.sh" "$TMP/engram-store" "$TMP/bad-request" "$TMP/bad-response" && ok 'adapter rejects unknown and malformed fixed-verb requests' || no 'adapter accepted unknown or malformed request'
marker="$TMP/engram-payload-executed"; ! reject "$TMP/activation" activate-engram "bad;\$(touch $marker)" "$TMP/integrated" "$ROOT/tests/lib/rubric-engram-store.sh" "$TMP/engram-store" "$TMP/gate" && [ ! -e "$marker" ] && ok 'payload-like project and paths remain data under fixed argv' || no 'payload-like Engram input executed'
for payload in requirements.txt CMakeLists.txt README.sh README.mdx; do mkdir "$TMP/$payload"; rces_init "$TMP/$payload"; ! reject "$TMP/activation" activate-engram "bad;\$(touch $TMP/$payload-ran)" "$TMP/integrated" "$ROOT/tests/lib/rubric-engram-store.sh" "$TMP/$payload" "$TMP/gate" && [ ! -e "$TMP/$payload-ran" ] && ok "$payload remains non-executable data" || no "$payload was interpreted"; done
cp "$TMP/config-before" "$TMP/hybrid.yaml"; rces_init "$TMP/hybrid-store"; "$TMP/activation" activate-hybrid cnsic "$TMP/integrated" "$TMP/hybrid.yaml" "$TMP/hybrid.journal" "$ROOT/tests/lib/rubric-engram-store.sh" "$TMP/hybrid-store" "$TMP/gate" > "$TMP/hybrid-resolution" && grep -Fxq 'state=active' "$TMP/hybrid-resolution" && grep -Fxq 'current_intent=active' "$TMP/hybrid.journal" && grep -Fxq '    state: "active"' "$TMP/hybrid.yaml" && grep -Fxq 'state=active' <(rces_field "$TMP/hybrid-store/current" content_hex | xxd -r -p) && ok 'hybrid commits verified OpenSpec and Engram active surfaces in order' || no 'hybrid did not reach verified active surfaces'
cp "$TMP/hybrid.journal" "$TMP/hybrid.journal.once"; cp "$TMP/hybrid.yaml" "$TMP/hybrid.yaml.once"; cp "$TMP/hybrid-store/current" "$TMP/hybrid-store/current.once"; "$TMP/activation" activate-hybrid cnsic "$TMP/integrated" "$TMP/hybrid.yaml" "$TMP/hybrid.journal" "$ROOT/tests/lib/rubric-engram-store.sh" "$TMP/hybrid-store" "$TMP/gate" > "$TMP/hybrid-replay" && cmp -s "$TMP/hybrid.journal.once" "$TMP/hybrid.journal" && cmp -s "$TMP/hybrid.yaml.once" "$TMP/hybrid.yaml" && cmp -s "$TMP/hybrid-store/current.once" "$TMP/hybrid-store/current" && cmp -s "$TMP/hybrid-resolution" "$TMP/hybrid-replay" && ok 'same transaction active replay is byte-idempotent' || no 'same transaction active replay rewrote active state'
cp -a "$TMP/integrated" "$TMP/hybrid-different"; put "$TMP/hybrid-different/rows/source/mode" strict-tdd; rccf_rebuild_confirmation "$TMP/hybrid-different"; ! reject "$TMP/activation" activate-hybrid cnsic "$TMP/hybrid-different" "$TMP/hybrid.yaml" "$TMP/hybrid.journal" "$ROOT/tests/lib/rubric-engram-store.sh" "$TMP/hybrid-store" "$TMP/gate" && cmp -s "$TMP/hybrid.journal.once" "$TMP/hybrid.journal" && ok 'different transaction cannot reuse active journal' || no 'different transaction reused journal'
# The production program exposes only stable comments.  Each runner copy crashes
# through sed; activation has no environment-variable or test-only bypass.
crash_points=(F1-before-intent F1-after-intent F1-before-write F1-after-write F1-before-readback F1-after-readback F2-before-intent F2-after-intent F2-before-write F2-after-write F2-before-readback F2-after-readback F3-before-intent F3-after-intent F3-before-write F3-after-write F3-before-readback F3-after-readback F4-before-intent F4-after-intent F4-before-write F4-after-write F4-before-readback F4-after-readback)
crash_ok=1
for point in "${crash_points[@]}"; do
