  cp "$TMP/config-before" "$TMP/$point.yaml"; rces_init "$TMP/$point-store"
  ! reject "$runner" activate-hybrid cnsic "$TMP/integrated" "$TMP/$point.yaml" "$TMP/$point.journal" "$ROOT/tests/lib/rubric-engram-store.sh" "$TMP/$point-store" "$TMP/gate" || crash_ok=0
  case "$point" in *-after-*|F[2-4]-before-*) [ -f "$TMP/$point.journal" ] || crash_ok=0;; esac
  "$TMP/activation" activate-hybrid cnsic "$TMP/integrated" "$TMP/$point.yaml" "$TMP/$point.journal" "$ROOT/tests/lib/rubric-engram-store.sh" "$TMP/$point-store" "$TMP/gate" > "$TMP/$point.out" || crash_ok=0
  grep -Fxq 'state=active' "$TMP/$point.out" && grep -Fxq 'current_intent=active' "$TMP/$point.journal" || crash_ok=0
done
[ "$crash_ok" = 1 ] && ok 'F1-F4 write-ahead crash matrix resumes only from independently verified intents' || no 'write-ahead crash matrix did not resume safely'
compcase() {
  local runner=$1 name=$2 want=$3 yaml journal store; yaml="$TMP/$name.yaml"; journal="$TMP/$name.journal"; store="$TMP/$name-store"
  cp "$TMP/config-before" "$yaml"; cp "$yaml" "$yaml.raw"; printf 'raw %s\n' "$name" > "$TMP/$name.raw"; rces_init "$store"; rces_seed "$store" sdd-init/cnsic "$TMP/$name.raw"
  "$runner" activate-hybrid cnsic "$TMP/integrated" "$yaml" "$journal" "$ROOT/tests/lib/rubric-engram-store.sh" "$store" "$TMP/gate" >/dev/null || :
  "$TMP/activation" activate-hybrid cnsic "$TMP/integrated" "$yaml" "$journal" "$ROOT/tests/lib/rubric-engram-store.sh" "$store" "$TMP/gate" >/dev/null || return 1
  actual_rev=$(rces_field "$store/current" store_revision); [ "$actual_rev" = "$(field "$journal" engram_restore_revision)" ] || return 1; case "$name" in *F2-*|*F3-*|*F4-*) [ "$actual_rev" != "$(field "$journal" engram_preimage_revision)" ] || return 1;; esac
  case "$want" in prior-active) cmp -s "$yaml.raw" "$yaml" && cmp -s "$TMP/$name.raw" <(rces_field "$store/current" content_hex | xxd -r -p) && grep -Fxq 'state=prior-active' "$journal" && grep -Fxq 'current_intent=prior-active' "$journal" && grep -Fxq 'verified_step=C1-verified' "$journal";; active) grep -Fxq 'state=active' "$journal" && grep -Fxq 'current_intent=active' "$journal";; esac || return 1
  cp "$journal" "$journal.once"; cp "$yaml" "$yaml.once"; cp "$store/current" "$store/current.once"
  "$TMP/activation" activate-hybrid cnsic "$TMP/integrated" "$yaml" "$journal" "$ROOT/tests/lib/rubric-engram-store.sh" "$store" "$TMP/gate" >/dev/null && cmp -s "$journal.once" "$journal" && cmp -s "$yaml.once" "$yaml" && cmp -s "$store/current.once" "$store/current"
}
comp_ok=1
for spec in 'F1-completed:prior-active' 'F2-completed:prior-active' 'F3-completed:prior-active' 'F4-before-terminal:prior-active'; do
  point=${spec%%:*}; want=${spec#*:}; runner="$TMP/forward-failure-$point"; sed "/# fault:$point\$/a return 77" "$TMP/activation" > "$runner"; chmod +x "$runner"; compcase "$runner" "forward-failure-$point" "$want" || comp_ok=0
done
[ "$comp_ok" = 1 ] && ok 'F1-F4 deterministic failures restore exact raw preimages or retain verified active terminals' || no 'forward failure compensation or terminal replay failed'
c_ok=1
for point in C1-before-intent C1-after-intent C1-before-write C1-after-write C1-before-readback C1-after-readback C2-before-intent C2-after-intent C2-before-write C2-after-write C2-before-readback C2-after-readback C3-before-intent C3-after-intent C3-before-write C3-after-write C3-before-readback C3-after-readback C4-before-intent C4-after-intent C4-before-write C4-after-write C4-before-readback C4-after-readback; do
