  "$runner" activate-hybrid cnsic "$TMP/integrated" "$TMP/$point.yaml" "$TMP/$point.journal" "$ROOT/tests/lib/rubric-engram-store.sh" "$TMP/$point-store" "$TMP/gate" >/dev/null 2>&1; [ "$?" = 75 ] || { printf 'marker missed: %s\n' "$point" >&2; c_ok=0; }
  "$TMP/activation" activate-hybrid cnsic "$TMP/integrated" "$TMP/$point.yaml" "$TMP/$point.journal" "$ROOT/tests/lib/rubric-engram-store.sh" "$TMP/$point-store" "$TMP/gate" >/dev/null && cmp -s "$TMP/$point.raw" "$TMP/$point.yaml" && cmp -s "$TMP/$point.raw.engram" <(rces_field "$TMP/$point-store/current" content_hex | xxd -r -p) && grep -Fxq 'state=prior-active' "$TMP/$point.journal" && grep -Fxq 'current_intent=prior-active' "$TMP/$point.journal" || { printf 'resume failed: %s\n' "$point" >&2; c_ok=0; }
done
[ "$c_ok" = 1 ] && ok 'C1-C4 write-ahead compensation crash matrix restores exact raw surfaces' || no 'compensation crash matrix did not resume safely'
cp "$TMP/hybrid.journal" "$TMP/stale.journal"; sed -i 's/^generation=.*/generation=0/' "$TMP/stale.journal"; cp "$TMP/stale.journal" "$TMP/stale.once"; ! reject "$TMP/activation" activate-hybrid cnsic "$TMP/integrated" "$TMP/hybrid.yaml" "$TMP/stale.journal" "$ROOT/tests/lib/rubric-engram-store.sh" "$TMP/hybrid-store" "$TMP/gate" && cmp -s "$TMP/stale.once" "$TMP/stale.journal" && ok 'stale journal generation rejects without overwrite' || no 'stale journal generation overwrote state'
cp "$TMP/config-before" "$TMP/conflict.yaml"; rces_init "$TMP/conflict-store"; "$TMP/activation" activate-hybrid cnsic "$TMP/integrated" "$TMP/conflict.yaml" "$TMP/conflict.journal" "$ROOT/tests/lib/rubric-engram-store.sh" "$TMP/conflict-store" "$TMP/gate" >/dev/null; printf 'conflict\n' >> "$TMP/conflict.yaml"; ! reject "$TMP/activation" activate-hybrid cnsic "$TMP/integrated" "$TMP/conflict.yaml" "$TMP/conflict.journal" "$ROOT/tests/lib/rubric-engram-store.sh" "$TMP/conflict-store" "$TMP/gate" && grep -Fxq 'state=recovery-required' "$TMP/conflict.journal" && ok 'unexpected independently read surface becomes recovery-required' || no 'unexpected surface was not retained for recovery'
[ ! -e "$TMP/integrated/activation/unit1a-result" ] && [ ! -e "$TMP/integrated/activation/semantic-result" ] && ok 'real integrated fixture has no activation markers' || no 'fixture retained activation markers'
if "$TMP/gate" verify-integrated "$TMP/integrated" "$TMP/one" && "$TMP/gate" verify-integrated "$TMP/integrated" "$TMP/two" && cmp -s "$TMP/one" "$TMP/two" && receipt "$TMP/one" && model "$TMP/one" | grep -Fq 'CanonicalPolicyModelV1' && model "$TMP/one" | grep -Fq 'python' && model "$TMP/one" | grep -Fq 'pytest'; then ok 'verified integrated receipt is byte-identical, complete, and content-bound'; else no 'verified integrated receipt'; fi
for kind in marker shallow unconfirmed open unknown unsatisfied identity; do cp -a "$TMP/integrated" "$TMP/$kind"; case "$kind" in marker) mkdir -p "$TMP/$kind/activation"; put "$TMP/$kind/activation/unit1a-result" structure-valid/pending;; shallow) rm -rf "${TMP:?}/$kind"; mkdir "$TMP/$kind"; put "$TMP/$kind/activation/unit1a-result" structure-valid/pending;; unconfirmed) put "$TMP/$kind/rows/source/state" pending;; open) put "$TMP/$kind/questions/source/state" open;; unknown) put "$TMP/$kind/facts/declaration/status" unknown;; unsatisfied) put "$TMP/$kind/attestations/000/status" unsatisfied;; identity) put "$TMP/$kind/rows/source/id" stale;; esac; ! reject "$TMP/gate" verify-integrated "$TMP/$kind" "$TMP/$kind-receipt" && [ ! -e "$TMP/$kind-receipt" ] && ok "$kind input rejects without receipt" || no "$kind input was accepted"; done
cp -a "$TMP/integrated" "$TMP/policy"; put "$TMP/policy/rows/source/mode" strict-tdd; rccf_rebuild_confirmation "$TMP/policy"; "$TMP/validator" "$TMP/policy" >/dev/null && "$TMP/gate" verify-integrated "$TMP/policy" "$TMP/policy-receipt" && [ "$(field "$TMP/one" integrated_bundle_digest)" != "$(field "$TMP/policy-receipt" integrated_bundle_digest)" ] && [ "$(field "$TMP/one" canonical_model_digest)" != "$(field "$TMP/policy-receipt" canonical_model_digest)" ] && ok 'policy-relevant canonical data changes both bundle and model receipts' || no 'policy-relevant drift was not bound'
cp -a "$TMP/integrated" "$TMP/reordered"; mv "$TMP/reordered/rows/source" "$TMP/reordered/rows/zzz"; mv "$TMP/reordered/rows/default" "$TMP/reordered/rows/aaa"; mv "$TMP/reordered/bindings/unit" "$TMP/reordered/bindings/binding-renamed"; "$TMP/gate" verify-integrated "$TMP/reordered" "$TMP/reordered-receipt" && [ "$(field "$TMP/one" canonical_model_bytes)" = "$(field "$TMP/reordered-receipt" canonical_model_bytes)" ] && [ "$(field "$TMP/one" canonical_model_digest)" = "$(field "$TMP/reordered-receipt" canonical_model_digest)" ] && ok 'canonical model ignores record directory names and enumeration order' || no 'directory names or enumeration changed canonical model'
for kind in missing-binding missing-fact missing-attestation duplicate-id incomplete-binding; do cp -a "$TMP/integrated" "$TMP/$kind"; case "$kind" in missing-binding) rm -rf "$TMP/$kind/bindings/unit";; missing-fact) rm -rf "$TMP/$kind/facts/declaration";; missing-attestation) rm -rf "$TMP/$kind/attestations/000";; duplicate-id) cp -a "$TMP/$kind/bindings/unit" "$TMP/$kind/bindings/duplicate";; incomplete-binding) rm -f "$TMP/$kind/bindings/unit/signature-coverage";; esac; ! reject "$TMP/gate" verify-integrated "$TMP/$kind" "$TMP/$kind-receipt" && [ ! -e "$TMP/$kind-receipt" ] && ok "$kind model input rejects without receipt" || no "$kind model input was accepted"; done
cp -a "$TMP/integrated" "$TMP/scalar-data"; put "$TMP/scalar-data/rows/source/confirmation-answer" 'yaml: [data]; $(touch never) | multiline-like'; rccf_rebuild_confirmation "$TMP/scalar-data"; "$TMP/gate" verify-integrated "$TMP/scalar-data" "$TMP/scalar-data-receipt" && model "$TMP/scalar-data-receipt" | grep -Fq 'yaml: [data]; $(touch never) | multiline-like' && [ ! -e "$TMP/never" ] && ok 'delimiter YAML and shell-like scalar remains unambiguous data' || no 'delimiter scalar was executed or ambiguous'
cp -a "$TMP/integrated" "$TMP/nul"; printf 'nul\000\n' > "$TMP/nul/rows/source/confirmation-answer"; ! reject "$TMP/gate" verify-integrated "$TMP/nul" "$TMP/nul-receipt" && ok 'NUL scalar rejects without receipt' || no 'NUL scalar was accepted'
cp -a "$TMP/integrated" "$TMP/source"; printf drift >> "$(rccf_get "$TMP/source/root")/AGENTS.md"; ! reject "$TMP/gate" verify-integrated "$TMP/source" "$TMP/source-receipt" && [ ! -e "$TMP/source-receipt" ] && ok 'source input rejects without receipt' || no 'source input was accepted'
[ ! -e "$TMP/candidate-ran" ] && ok 'candidate data never executes' || no 'candidate data executed'
printf '\n%d passed, %d failed\n' "$PASS" "$FAIL"; [ "$FAIL" -eq 0 ]
